using System.Globalization; using System.Windows; using AutoPecasERP.Core.Entities; using AutoPecasERP.Data.Context; namespace AutoPecasERP.Desktop.Views; public partial class ClienteEditWindow:Window{public ClienteEditWindow(){InitializeComponent();}async void Salvar_Click(object s,RoutedEventArgs e){if(string.IsNullOrWhiteSpace(Nome.Text)){MessageBox.Show("Informe o nome.");return;}decimal.TryParse(Limite.Text.Replace(",","."),NumberStyles.Any,CultureInfo.InvariantCulture,out var lim);using var db=new ErpDbContext();db.Clientes.Add(new Cliente{Nome=Nome.Text.Trim(),RazaoSocial=Razao.Text.Trim(),CpfCnpj=Doc.Text.Trim(),Telefone=Telefone.Text.Trim(),WhatsApp=Telefone.Text.Trim(),Endereco=Endereco.Text.Trim(),Cidade=Cidade.Text.Trim(),Estado=Estado.Text.Trim().ToUpper(),LimiteCredito=lim});await db.SaveChangesAsync();DialogResult=true;}}